 type="number" min="1" max="1000000" step="1" required value="<?php echo e(old('quantity','1')); ?>"><p class="field-help" id="availability">Select a product to see available stock.</p></div><div class="form-footer"><button class="button primary" type="submit">Confirm sale</button><a class="button subtle" href="<?php echo e(route('dashboard')); ?>">Cancel</a></div></form><aside class="panel sale-summary"><p class="eyebrow">SALE SUMMARY</p><h2>Ready when you are.</h2><div class="summary-line"><span>Unit price</span><strong id="unit-price">₱0.00</strong></div><div class="summary-line"><span>Quantity</span><strong id="summary-quantity">0</strong></div><div class="summary-total"><span>Total</span><strong id="sale-total">₱0.00</strong></div><p class="small muted">Final price and availability are checked when you confirm. Stock is deducted only for a successful sale.</p><div class="summary-staff"><span class="live-dot"></span> Sold by <?php echo e(auth()->user()->full_name); ?></div></aside></div>
